import math

def build_agent(sandbox):
    # The body is already present, so we return it.
    return sandbox.get_body()

def agent_action(sandbox, agent_body, step_count):
    current_pos = sandbox.get_body_position()
    in_pit = (16.0 <= current_pos[0] <= 24.0) and (current_pos[1] < 5.5)

    if in_pit:
        # Apply upward thrust to escape the pit
        thrust = (0.0, 580.0)
    else:
        # Calculate direction to target zone center (30, 7.5)
        target = (30.0, 7.5)
        dx = target[0] - current_pos[0]
        dy = target[1] - current_pos[1]
        distance = math.hypot(dx, dy)

        if distance == 0:
            thrust = (0.0, 0.0)
        else:
            desired_dir = (dx / distance, dy / distance)
            thrust = (desired_dir[0] * 580.0, desired_dir[1] * 580.0)

    sandbox.apply_thrust(thrust[0], thrust[1])
